// The SPKI pin against Go's lantls.PinOf (Fixtures/pin_vector.json, generated by
// ios/scripts/gen-pin-vector.go) and the pin-mismatch re-proof against reader_proof.json.
import Security
import XCTest

final class ReaderPinTests: XCTestCase {
    private let v = Golden.fixture("pin_vector")

    private func cert(_ key: String) throws -> SecCertificate {
        let der = try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(v[key] as? String)))
        return try XCTUnwrap(SecCertificateCreateWithData(nil, der as CFData))
    }

    func testP256PinEqualsTheGoPin() throws {
        XCTAssertEqual(SpkiPin.pin(ofCertificate: try cert("p256_cert")), v["p256_pin"] as? String)
    }

    func testAP384KeyIsRefused() throws {
        XCTAssertNil(SpkiPin.pin(ofCertificate: try cert("p384_cert")))
        XCTAssertEqual(SpkiPin.decide(leaf: try cert("p384_cert"), pinned: v["p384_pin"] as! String), .reject, "fail closed even with the right pin string")
    }

    func testAnRsaKeyIsRefused() throws {
        XCTAssertNil(SpkiPin.pin(ofCertificate: try cert("rsa_cert")))
    }

    func testAPointThatIsNotUncompressedP256IsRefused() {
        XCTAssertNil(SpkiPin.pin(ofP256Point: Data(repeating: 4, count: 64)))
        XCTAssertNil(SpkiPin.pin(ofP256Point: Data([0x02]) + Data(repeating: 1, count: 64)))
    }

    func testMatchingPinIsTrustedAndAnyOtherIsRejectedBeforeARequestExists() throws {
        let leaf = try cert("p256_cert")
        XCTAssertEqual(SpkiPin.decide(leaf: leaf, pinned: v["p256_pin"] as! String), .trust)
        // the decision is made in the server-trust challenge, so a reject means no request (no Bearer) is ever written
        XCTAssertEqual(SpkiPin.decide(leaf: leaf, pinned: String(repeating: "0", count: 64)), .reject)
        XCTAssertEqual(SpkiPin.decide(leaf: leaf, pinned: ""), .reject)
        XCTAssertEqual(SpkiPin.decide(leaf: nil, pinned: v["p256_pin"] as! String), .reject)
    }

    func testPinComparisonIsExact() {
        XCTAssertTrue(SpkiPin.matches("abc", "abc"))
        XCTAssertFalse(SpkiPin.matches("abc", "abd"))
        XCTAssertFalse(SpkiPin.matches("abc", "ab"))
        XCTAssertFalse(SpkiPin.matches("", ""))
    }
}

final class ReaderReProofTests: XCTestCase {
    var http: FakeHttp!
    var now: Int64 = 5_000_000
    var proof: PinReProof!
    let g = Golden.json("proof")

    override func setUp() {
        super.setUp()
        http = FakeHttp()
        let nonce = (g["request"] as! [String: String])["nonce"]!
        proof = PinReProof(http: http, rand: { nonce }, nowMs: { [unowned self] in self.now })
    }

    private var creds: ReaderCredentials {
        ReaderCredentials(address: "192.0.2.20:8080", readerId: "rd_fixture", bearer: g["bearer"] as! String, pin: "oldpin")
    }

    private func answer(proof: String? = nil, pin: String? = nil, status: Int = 200) -> PairAnswer {
        var d = (g["response"] as! [String: Any])["data"] as! [String: Any]
        if let proof { d["proof"] = proof }
        return .init(status: status, body: ReaderFrames.serialise(["data": d, "error": NSNull()]), pin: pin ?? (g["pin_seen"] as? String))
    }

    func testTheBearerHashMatchesTheFixture() {
        XCTAssertEqual(ReaderCrypto.sha256Hex(g["bearer"] as! String), g["bearer_hash_hex"] as? String)
    }

    func testAGoodProofAdoptsOnlyTheSeenPin() {
        http.answers = [answer()]
        var want = creds
        want.pin = g["pin_seen"] as! String
        XCTAssertEqual(proof.attempt(creds), .adopted(want))
        let r = http.requests.first
        XCTAssertEqual(r?.url, "https://192.0.2.20:8080/api/sync/primary-proof")
        XCTAssertFalse(r?.body.contains(g["bearer"] as! String) ?? true, "the bearer never goes out")
        XCTAssertNil(r?.expectPin, "an unverified connection: it records the pin it saw")
    }

    func testAWrongProofIsAMismatchAndKeepsTheOldPin() {
        http.answers = [answer(proof: String(repeating: "0", count: 64))]
        XCTAssertEqual(proof.attempt(creds), .mismatch)
    }

    func testAProofForAnotherPinSeenIsAMismatch() {
        http.answers = [answer(pin: String(repeating: "f", count: 64))]
        XCTAssertEqual(proof.attempt(creds), .mismatch)
    }

    func testNoAnswerOr404IsUnreachableNeverARevoke() {
        http.answers = [answer(status: 404)]
        XCTAssertEqual(proof.attempt(creds), .unreachable)
        now += 31_000
        http.answers = [.init(status: -1, body: "", pin: nil)]
        XCTAssertEqual(proof.attempt(creds), .unreachable)
    }

    func testAtMostOneAttemptPerThirtySeconds() {
        http.answers = [answer(), answer()]
        _ = proof.attempt(creds)
        now += 29_999
        XCTAssertEqual(proof.attempt(creds), .tooSoon)
        now += 1
        XCTAssertNotEqual(proof.attempt(creds), .tooSoon)
    }

    func testAMissingPrimaryIdOrBodyIsAMismatch() {
        http.answers = [.init(status: 200, body: "{}", pin: g["pin_seen"] as? String)]
        XCTAssertEqual(proof.attempt(creds), .mismatch)
    }
}
